INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(7901, '2 Samuel 15:27', '2 Samuel', 15, 27, '&nbsp;نو هغۀ صدوق ته داسې وئيل، ”ګوره، خپل زوئ اخيمعض او د ابياتار زوئ يونتن د ځان سره کړه او په خېر سره واپس ښار ته لاړ شئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7902, '2 Samuel 15:28', '2 Samuel', 15, 28, '&nbsp;زۀ به په صحرا کښې د سيند د ګودر په غاړه انتظار کوم تر دې پورې چې ستاسو نه خبر راورسيږى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7903, '2 Samuel 15:29', '2 Samuel', 15, 29, '&nbsp;نو صدوق او ابياتار د لوظ صندوق واپس يروشلم ته يوړو او هلته ايسار شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7904, '2 Samuel 15:30', '2 Samuel', 15, 30, '&nbsp;داؤد په ژړا ژړا د زيتُونو غرۀ ته وختلو، څپلۍ د هغۀ په پښو نۀ وې او د خفګان نه يې خپل سر پټ کړے وو. چې په هغۀ پسې څوک راروان وُو نو هغوئ هم سرونه پټ کړى وُو او ژړل يې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7905, '2 Samuel 15:31', '2 Samuel', 15, 31, '&nbsp;کله چې داؤد خبر شو چې اخى‌تُفل په بغاوت کښې د ابى‌سلوم سره ملګرے شوے دے نو هغۀ داسې دُعا وکړه، ”مالِکه خُدايه، زۀ تا ته سوال کوم چې د اخى‌تُفل مشوره په کم عقلتوب بدله کړه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7906, '2 Samuel 15:32', '2 Samuel', 15, 32, '&nbsp;کله چې داؤد د غرۀ سر ته ورسېدو، چرته چې د عبادت يو ځائ وو، نو خپل يو اعتبارى ملګرے حوسى، ارکے ورسره مِلاو شو، هغۀ خپلې جامې شلولې وې او په سر يې خاورې پرَتى وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7907, '2 Samuel 15:33', '2 Samuel', 15, 33, '&nbsp;داؤد هغۀ ته وفرمائيل، ”کۀ تۀ ما سره ځې نو تۀ به زمونږ دپاره لانجه جوړه کړې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7908, '2 Samuel 15:34', '2 Samuel', 15, 34, '&nbsp;خو تۀ ما سره دا ښۀ کولے شې چې ښار ته واپس شې او ابى‌سلوم ته ووائې چې تۀ به اوس په وفادارۍ سره د هغۀ خِدمت کوې لکه څنګه چې دې د هغۀ د پلار خِدمت کړے وو. او د اخى‌تُفل د مشورې ډېر مخالفت کوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7909, '2 Samuel 15:35', '2 Samuel', 15, 35, '&nbsp;صدوق او ابياتار اِمامان به هلته وى، چې تۀ د بادشاه په محل کښې څۀ هم اورې نو هغوئ ته وايه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7910, '2 Samuel 15:36', '2 Samuel', 15, 36, '&nbsp;د هغوئ زامن اخيمعض او يونتن د هغوئ سره دى، هغوئ د هغه ټولو معلوماتو سره ما له راولېږه چې تا راجمع کړى وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7911, '2 Samuel 15:37', '2 Samuel', 15, 37, '&nbsp;نو د داؤد ملګرے حوسى د ابى‌سلوم د رارسېدو سره سم ښار ته راوګرځېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7912, '2 Samuel 16:1', '2 Samuel', 16, 1, '&nbsp;کله چې داؤد د غرۀ د سر نه لږ مخکښې تلے وو، نو هغه ناڅاپه د مفيبوست د نوکر ضيبا سره مِلاو شو، د هغۀ سره دوه خرونه وُو چې دوه سوو ډوډو، يو سل موټى کشمشو، سل موټى د اوړى مېوو او د ميو ډکه يوه مشکيزه پرې بار وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7913, '2 Samuel 16:2', '2 Samuel', 16, 2, '&nbsp;داؤد بادشاه ترې نه تپوس وکړو، ”تۀ په دې ټولو څيزونو باندې څۀ کوې؟“ ضيبا ورته ووئيل، ”بادشاه سلامت، خرۀ ستا د خاندان د سورلۍ دپاره دى، روټۍ او مېوې د دې سړو د خوراک دپاره دى او مے د دوئ د څښلو دپاره دى چې کله دوئ په صحرا کښې ستړى وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7914, '2 Samuel 16:3', '2 Samuel', 16, 3, '&nbsp;بادشاه ترې نه تپوس وکړو، ”ستا د نېک ساؤل نمسے مفيبوست چرته دے؟“ ضيبا ورته ووئيل، ”هغه په يروشلم کښې ايسار دے، ځکه چې د هغۀ خيال دا دے چې بنى اِسرائيليان به هغۀ له د هغۀ د نيکۀ ساؤل بادشاهى بيا ورکړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7915, '2 Samuel 16:4', '2 Samuel', 16, 4, '&nbsp;بادشاه ضيبا ته وفرمائيل، ”د مفيبوست سره چې څۀ هم دى هغه ستا شول.“ ضيبا جواب ورکړو، ”زۀ ستا په وړاندې د عزت نه ټيټېږم، بادشاه سلامت، تۀ دې زما نه همېشه خوشحاله اوسې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7916, '2 Samuel 16:5', '2 Samuel', 16, 5, '&nbsp;کله چې داؤد بادشاه بحوريم ته ورسېدو، نو د ساؤل يو خپلوان د جيرا زوئ سِمعى د مِلاوېدو دپاره ورله راووتلو، کله چې هغه راروان وو نو کنځل يې کول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7917, '2 Samuel 16:6', '2 Samuel', 16, 6, '&nbsp;سِمعى داؤد او د هغۀ آفسران په کاڼو وويشتل، اګر چې د داؤد سره خپل سړى او فوجيان هم څنګ په څنګ ولاړ وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7918, '2 Samuel 16:7', '2 Samuel', 16, 7, '&nbsp;سِمعى کنځلې کولې او وې ووئيل، ”اوځه، اوځه. قاتِله، مجرمه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7919, '2 Samuel 16:8', '2 Samuel', 16, 8, '&nbsp;تا د ساؤل نه بادشاهى واخستله او اوس مالِک خُدائ ستا نه بدله اخلى ځکه چې تا د ساؤل د خاندان ډېر کسان وژلى دى. مالِک خُدائ ستا زوئ ابى‌سلوم له بادشاهى ورکړې ده، اے قاتِله، تۀ تباه يې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7920, '2 Samuel 16:9', '2 Samuel', 16, 9, '&nbsp;ابيشى ووئيل چې د هغۀ مور ضروياه وه، ”بادشاه سلامت، تا دا مردار سپے ولې پرېښودو چې کنځلې درته وکړى؟ ما له اجازت راکړه چې زۀ ورشم او سر ترې نه پرې کړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7921, '2 Samuel 16:10', '2 Samuel', 16, 10, '&nbsp;بادشاه ابيشى او د هغۀ ورور يوآب ته وفرمائيل، ”دا ستا کار نۀ دے. کۀ هغه ما ته کنځل کوى او هغۀ ته مالِک خُدائ دا فرمائيلى وى، نو څوک دا حق لرى چې تپوس ترې نه وکړى چې دا ولې کوې؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7922, '2 Samuel 16:11', '2 Samuel', 16, 11, '&nbsp;نو داؤد ابيشى او خپلو ټولو آفسرانو ته وفرمائيل، ”زما خپل زوئ زما د وژلو کوشش کوى، تاسو په دې بنيامينى باندې ولې حېرانېږئ؟ مالِک خُدائ ورته فرمائيلى دى چې ما ته کنځلې وکړى، نو هغه پرېږدئ چې هم داسې کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7923, '2 Samuel 16:12', '2 Samuel', 16, 12, '&nbsp;کېدے شى چې مالِک خُدائ زما مشکل ووينى او نن ما سره د دې کنځلو په بدل کښې ښۀ وکړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7924, '2 Samuel 16:13', '2 Samuel', 16, 13, '&nbsp;نو داؤد او د هغۀ سړى په لاره روان وُو. سِمعى هم په نزدې غر باندې روان وو، هغۀ کنځلې کولې او په روانه کښې يې هغوئ په کاڼو ويشتل او خاورې يې پرې اچولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7925, '2 Samuel 16:14', '2 Samuel', 16, 14, '&nbsp;کله چې بادشاه او د هغۀ ټول سړى اُردن ته ورسېدل نو هغوئ سخت ستړى وُو او هلته هغوئ آرام وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7926, '2 Samuel 16:15', '2 Samuel', 16, 15, '&nbsp;ابى‌سلوم او د هغۀ سره ټول بنى اِسرائيليان يروشلم ته ننوتل او اخى‌تُفل د هغوئ سره وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7927, '2 Samuel 16:16', '2 Samuel', 16, 16, '&nbsp;کله چې د داؤد اعتبارى ملګرے حوسى د ابى‌سلوم سره مِلاو شو نو هغۀ چغه کړه، ”بادشاه سلامت، زنده‌باد. بادشاه سلامت، زنده‌باد.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7928, '2 Samuel 16:17', '2 Samuel', 16, 17, '&nbsp;ابى‌سلوم ترې نه تپوس وکړو، ”ستا د خپل دوست داؤد سره وفادارى چرته لاړه؟ تۀ د هغۀ سره ولې لا نۀ ړې؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7929, '2 Samuel 16:18', '2 Samuel', 16, 18, '&nbsp;حوسى ورته ووئيل، ”ما داسې څنګه کړى وے؟ زۀ د هغه چا په طرف يم چې څوک د مالِک خُدائ، دې خلقو او ټولو بنى اِسرائيلو خوښ کړے وى. زۀ به تا سره ايسار شم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7930, '2 Samuel 16:19', '2 Samuel', 16, 19, '&nbsp;د دې نه علاوه، زۀ چې د خپل نېک د زوئ خِدمت نۀ کوم نو د چا به کوم؟ څنګه چې ما ستا د پلار خِدمت کړے دے، نو زۀ به ستا خِدمت هم کوم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7931, '2 Samuel 16:20', '2 Samuel', 16, 20, '&nbsp;بيا ابى‌سلوم اخى‌تُفل ته وروګرځېدو او ورته يې ووئيل، ”تۀ مونږ له خپله مشوره راکړه چې مونږ څۀ وکړُو؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7932, '2 Samuel 16:21', '2 Samuel', 16, 21, '&nbsp;اخى‌تُفل ورته ووئيل، ”لاړ شه او د خپل پلار د وينځو سره څمله کومې يې چې د ځان نه وروستو پرېښودلې دى چې د محل خيال ساتى. نو بيا به په بنى اِسرائيلو کښې هر چا ته پته ولګى چې تا په څرګنده د خپل پلار بې‌عزتى کړې ده نو داسې ستا ملګرى به نور هم تکړه شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7933, '2 Samuel 16:22', '2 Samuel', 16, 22, '&nbsp;نو هغوئ د محل په چت باندې د ابى‌سلوم دپاره يوه خېمه ولګوله او د ټولو خلقو په مخکښې ابى‌سلوم ورننوتلو او د خپل پلار د وينځو سره څملاستو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7934, '2 Samuel 16:23', '2 Samuel', 16, 23, '&nbsp;په هغه ورځو کښې به چې اخى‌تُفل کومه مشوره ورکوله نو هغه به داسې منلے شوه لکه چې دا بلکل د خُدائ پاک خبره وى، داؤد او ابى‌سلوم دواړو به منله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7935, '2 Samuel 17:1', '2 Samuel', 17, 1, '&nbsp;د هغې ډېر وخت نۀ وو شوے چې اخى‌تُفل ابى‌سلوم ته ووئيل، ”ما پرېږده چې دولس زره سړى خوښ کړم او نن شپه زۀ په داؤد پسې روان شم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7936, '2 Samuel 17:2', '2 Samuel', 17, 2, '&nbsp;کله چې هغه ستړے او بې‌حوصلې وى نو زۀ به په هغۀ حمله وکړم. هغه به ويريږى او د هغۀ ټول سړى به وتښتى. او زۀ به صِرف بادشاه ووژنم', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7937, '2 Samuel 17:3', '2 Samuel', 17, 3, '&nbsp;او بيا به د هغۀ ټول سړى تا له داسې واپس راولم، لکه چې ناوې خپل خاوند له راځى. تاسو غواړئ چې دا يو کس ووژنئ نو باقى نورو خلقو ته به خېر شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7938, '2 Samuel 17:4', '2 Samuel', 17, 4, '&nbsp;دا خبره ابى‌سلوم او ټولو بنى اِسرائيلى مشرانو ته ښۀ معلومه شوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7939, '2 Samuel 17:5', '2 Samuel', 17, 5, '&nbsp;ابى‌سلوم ووئيل، ”اوس حوسى راوغواړه او چې هغه څۀ وائى نو هغۀ ته به غوږ ونيسو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7940, '2 Samuel 17:6', '2 Samuel', 17, 6, '&nbsp;کله چې حوسى راورسېدو نو ابى‌سلوم ورته ووئيل، ”دا هغه مشوره ده چې اخى‌تُفل مونږ له راکړې ده، مونږ له پرې عمل کول په کار دى او کۀ نه؟ کۀ تۀ وائې چې نۀ نو بيا تۀ مونږ ته ووايه چې څۀ وکړُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7941, '2 Samuel 17:7', '2 Samuel', 17, 7, '&nbsp;حوسى ورته ووئيل، ”دې ځل چې اخى‌تُفل کومه مشوره درکړې ده هغه ښۀ نۀ ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7942, '2 Samuel 17:8', '2 Samuel', 17, 8, '&nbsp;تا ته پته ده چې ستا پلار او د هغۀ سړى تکړه جنګ کوونکى دى او هغوئ داسې غصه دى لکه چې د يو مېلو نه بچى تښتولے شوى وى. ستا پلار يو تجربه‌کار فوجى دے او د شپې د خپلو سړو سره نۀ ايساريږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7943, '2 Samuel 17:9', '2 Samuel', 17, 9, '&nbsp;کېدے شى چې اوس هم هغه په يو غار کښې يا په بل ځائ کښې پټ وى. چې څنګه داؤد ستا په سړو باندې حمله وکړى او چې هر څوک هم د دې نه خبر شى نو وائى به چې ستا ډېر فوجيان وژلى شوى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7944, '2 Samuel 17:10', '2 Samuel', 17, 10, '&nbsp;بيا به د ټولو نه تکړه سړے هم يريږى د چا چې د ازمرى په شان زړۀ وى ځکه چې په بنى اِسرائيلو کښې هر چا ته پته ده چې ستا پلار يو لوئ فوجى دے او د هغۀ سړى تکړه جنګ کوونکى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7945, '2 Samuel 17:11', '2 Samuel', 17, 11, '&nbsp;زما مشوره دا ده چې د مُلک د يو سر نه تر بل سره پورې ټول بنى اِسرائيليان راغونډ کړه، لکه چې د سمندر په غاړه څومره شګې دى، د دې دپاره چې تۀ په خپله په جنګ کښې د هغوئ نه مخکښې لاړ شې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7946, '2 Samuel 17:12', '2 Samuel', 17, 12, '&nbsp;داؤد چې هر چرته وى مونږ به يې پېدا کړُو او داسې به ورباندې وروغورزېږو لکه چې په زمکه باندې پرخه پرېوځى. هغه او د هغۀ سړى به ژوندى پاتې نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7947, '2 Samuel 17:13', '2 Samuel', 17, 13, '&nbsp;کۀ هغه ښار ته راوتښتى، نو زمونږ خلق به رسۍ راوړى او ښار به لاندې مېدان ته راکاږى. يو وړوکے کاڼے به هم پاتې نۀ شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7948, '2 Samuel 17:14', '2 Samuel', 17, 14, '&nbsp;ابى‌سلوم او ټولو بنى اِسرائيلو ووئيل، ”د حوسى مشوره د اخى‌تُفل د مشورې نه ښۀ ده.“ مالِک خُدائ دا فېصله کړې وه چې د اخى‌تُفل ښۀ مشوره به نۀ شى منلے، نو داسې هغه به په ابى‌سلوم باندې تباهى راولى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7949, '2 Samuel 17:15', '2 Samuel', 17, 15, '&nbsp;بيا حوسى صدوق او ابياتار اِمام ته ووئيل، ”دا هغه څۀ دى چې اخى‌تُفل ابى‌سلوم او د بنى اِسرائيلو مشرانو ته وئيلى دى او دا هغه څۀ دى چې ما يې مشوره ورکړې ده.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7950, '2 Samuel 17:16', '2 Samuel', 17, 16, '&nbsp;حوسى دا هم ووئيل، ”زر شئ، داؤد له پېغام ولېږئ چې د سيند سره هغه ځائ کښې شپه تېره نۀ کړى چرته چې اوبۀ کمې دى او خلق په کښې اوړى راوړى او د اُردن سيند نه دې سمدستى پورې وځى او صحرا ته دې لاړ شى، نو هغه او د هغۀ سړى به نۀ ګېريږى او نۀ به مرى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7951, '2 Samuel 17:17', '2 Samuel', 17, 17, '&nbsp;د ابياتار زوئ يونتن او د صدوق زوئ اخيمعض د عين‌راجل د چينې سره اِنتظار کولو، چې د يروشلم په بهرنۍ غاړه باندې وه، ځکه چې هغوئ دا جرأت نۀ شو کولے چې ښار ته د ننوتلو په وخت وليدے شى. يوه نوکره ښځه به هر وخت تلله او چې څۀ کېدل نو هغوئ ته به يې ووئيل او بيا به هغوئ تلل او داؤد بادشاه ته به يې وئيل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7952, '2 Samuel 17:18', '2 Samuel', 17, 18, '&nbsp;خو يوه ورځ يو هلک هغوئ وليدل او هغۀ ابى‌سلوم ته ووئيل، نو هغوئ تېز لاړل چې په بحوريم کښې د يو سړى په کور کښې پټ شى. د هغۀ د کور سره نزدې د هغۀ کوهے وو او هغوئ هغه کوهى ته ورکوز شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7953, '2 Samuel 17:19', '2 Samuel', 17, 19, '&nbsp;د هغه سړى ښځې تخته واخستله، د کوهى په خولۀ باندې يې کېښوده او په دې باندې يې غله وشيندله، نو چې هيڅ څوک دا شک ونۀ کړى چې هغوئ دلته وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7954, '2 Samuel 17:20', '2 Samuel', 17, 20, '&nbsp;د ابى‌سلوم آفسران هغه کور ته راغلل او د هغه ښځې نه يې تپوس وکړو، ”اخيمعض او يونتن چرته دى؟“ هغې ورته ووئيل، ”هغوئ د سيند نه پورې وتى دى.“ هغه سړو هغوئ ولټول خو پېدا يې نۀ کړل، نو هغوئ يروشلم ته راواپس شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7955, '2 Samuel 17:21', '2 Samuel', 17, 21, '&nbsp;د هغوئ د تلو نه پس، اخيمعض او يونتن د کوهى نه راووتل او لاړل او داؤد بادشاه له يې خبر ورسولو. هغوئ د هغۀ خِلاف د اخى‌تُفل د منصوبې نه خبر کړو او ورته يې ووئيل، ”زر شه، او د سيند نه پورې وځه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7956, '2 Samuel 17:22', '2 Samuel', 17, 22, '&nbsp;نو داؤد او د هغۀ ټول سړى د اُردن سيند نه په پورې وتلو شروع وکړه او تر سحر د رڼا پورې ټول بلې غاړې ته پورې وتل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7957, '2 Samuel 17:23', '2 Samuel', 17, 23, '&nbsp;کله چې اخى‌تُفل ته پته ولګېده چې د هغۀ په مشوره عمل نۀ دے شوے، نو هغۀ خپل خر کته کړو او خپل ښار ته واپس لاړو. کله چې هغۀ خپلې ټولې معاملې هوارې کړې نو هغۀ خپل ځان پهانسى کړو او مړ شو. هغه د خپل خاندان په اديره کښې ښخ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7958, '2 Samuel 17:24', '2 Samuel', 17, 24, '&nbsp;داؤد د محنايم ښار ته په هغه وخت رسېدلے وو چې څۀ وخت ابى‌سلوم او بنى اِسرائيليان د اُردن سيند نه پورې وتلى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7959, '2 Samuel 17:25', '2 Samuel', 17, 25, '&nbsp;ابى‌سلوم د يوآب په ځائ عماسا د لښکر مشر جوړ کړے وو. عماسا د اِسمٰعيلى اِتر زوئ وو، د هغۀ مور ابى‌جيل وه، چې هغه د ناحس لور او د يوآب د مور ضروياه خور وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7960, '2 Samuel 17:26', '2 Samuel', 17, 26, '&nbsp;ابى‌سلوم او د هغۀ سړو د جِلعاد په مُلک کښې خېمې لګولې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7961, '2 Samuel 17:27', '2 Samuel', 17, 27, '&nbsp;کله چې داؤد محنايم ته ورسېدو، نو هغه د ناحس د زوئ سوبى سره مِلاو شو، چې هغه په ربه ښار کښې د عمون د قبيلې وو، د عمى‌اېل زوئ مکير سره چې د لودبار وو او د جِلعاد د قبيلې د برزلى سره هم مِلاو شو، برزلى د راجليم وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7962, '2 Samuel 18:1', '2 Samuel', 18, 1, '&nbsp;داؤد بادشاه خپل ټول سړى راغونډ کړل او د زرو او سلو کسانو په ډلو کښې يې تقسيم کړل او په دوئ باندې يې د مشرۍ دپاره آفسران مقرر کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7963, '2 Samuel 18:2', '2 Samuel', 18, 2, '&nbsp;بيا يې هغوئ په درېو ډلو کښې ولېږل، چې د هرې يوې قبيلې خپل مشر وو، يوآب او د يوآب ورور ابيشے او د جات اِتے وو. او بادشاه خپلو سړو ته وفرمائيل، ”زۀ به په خپله تاسو سره ځم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7964, '2 Samuel 18:3', '2 Samuel', 18, 3, '&nbsp;خو هغوئ ورته ووئيل، ”تۀ به مونږ سره نۀ ځې، کۀ زمونږ باقى ټول کسان واپس شى او وتښتى نو په دشمن به څۀ فرق پرې نۀ وځى، يا کۀ زمونږ نيم کسان هم ووژلے شى، خو تۀ زمونږ د لسو زرو نه ښۀ يې. ښۀ به دا وى چې تۀ په ښار کښې ايسار شې او مونږ له مدد رالېږې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7965, '2 Samuel 18:4', '2 Samuel', 18, 4, '&nbsp;بادشاه ورته وفرمائيل، ”څۀ چې تاسو ته ښۀ ښکارى نو زۀ به هم هغه شان کوم.“ نو چې کله د هغۀ سړى د زرګونو او سلګونو په ډلو کښې روان وُو نو هغه د ښار د دروازې په خوا کښې ايسار شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7966, '2 Samuel 18:5', '2 Samuel', 18, 5, '&nbsp;هغۀ يوآب، ابيشى او اِتى له دا حُکم ورکړو، ”زما د خاطره ابى‌سلوم ته نقصان مۀ رسوئ.“ او چې داؤد دا حُکم خپلو آفسرانو له ورکولو نو ټولو فوجيانو واورېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7967, '2 Samuel 18:6', '2 Samuel', 18, 6, '&nbsp;د داؤد لښکر مېدان ته لاړو او د اِفرائيم په ځنګل کښې يې د بنى اِسرائيلو سره جنګ وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7968, '2 Samuel 18:7', '2 Samuel', 18, 7, '&nbsp;بنى اِسرائيلو د داؤد د سړو نه شکست وخوړو، او دا دومره سخت شکست وو چې په هغه ورځ شل زره سړى ووژلے شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7969, '2 Samuel 18:8', '2 Samuel', 18, 8, '&nbsp;جنګ په ټول مُلک کښې خور شو او چې په جنګ کښې څومره سړى مړۀ وُو نو د هغې نه زيات په ځنګل کښې مړۀ شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7970, '2 Samuel 18:9', '2 Samuel', 18, 9, '&nbsp;ابى‌سلوم ناڅاپه د داؤد يو څو سړو سره مِلاو شو. ابى‌سلوم په يو قچر باندې سور وو او قچر د څېړۍ يوې لوئې ونې لاندې ننوتلو، نو د ابى‌سلوم سر په څانګو کښې ونښتو. قچر منډه کړه او ابى‌سلوم په هوا کښې ترې نه ځوړند پاتې شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7971, '2 Samuel 18:10', '2 Samuel', 18, 10, '&nbsp;د داؤد يو سړى هغه وليدو او يوآب يې خبر کړو، ”صاحِبه، ما ابى‌سلوم وليدو چې د څېړۍ په ونه کښې ځوړند وو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7972, '2 Samuel 18:11', '2 Samuel', 18, 11, '&nbsp;يوآب ورته ووئيل، ”تا چې هغه وليدو نو هغه دې هم هلته ولې نۀ وژلو؟ نو ما به تا له په خپل لاس د سپينو زرو لس سيکې او يو فوجى کمربند درکړے وے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7973, '2 Samuel 18:12', '2 Samuel', 18, 12, '&nbsp;خو هغه سړى ورته ووئيل، ”کۀ تا ما له زر د سپينو زرو سيکې هم راکړے وے، نو ما به د بادشاه د زوئ خِلاف لاس نۀ وو اوچت کړے. مونږ ټولو اورېدلى دى چې بادشاه تا، ابيشى او اِتى له حُکم درکړے دے چې زما په خاطر ابى‌سلوم زلمى ته نقصان مۀ رسوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7974, '2 Samuel 18:13', '2 Samuel', 18, 13, '&nbsp;خو کۀ ما د بادشاه نافرمانى کړے وے او ابى‌سلوم مې وژلے وے، نو بادشاه به د دې نه خبر شوے وے، هغه د هر څۀ نه خبريږى او تا به زۀ نۀ وے بچ کړے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7975, '2 Samuel 18:14', '2 Samuel', 18, 14, '&nbsp;يوآب ووئيل، ”زۀ تا سره نور وخت نۀ ضائع کوم.“ هغۀ درې نېزې واخستلې او د ابى‌سلوم په سينه کښې يې ننويستلې چې هغه لا ژوندے وو او د څېړۍ په ونه کښې ځوړند وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7976, '2 Samuel 18:15', '2 Samuel', 18, 15, '&nbsp;بيا د يوآب لس فوجيان ابى‌سلوم ته رانزدې شول او هغه يې مړ کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7977, '2 Samuel 18:16', '2 Samuel', 18, 16, '&nbsp;نو يوآب حُکم وکړو چې د جنګ د ودرېدو دپاره دې شپېلۍ وغږولے شى او د هغۀ فوجيان په بنى اِسرائيلو پسې تلو نه راواپس شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7978, '2 Samuel 18:17', '2 Samuel', 18, 17, '&nbsp;هغوئ د ابى‌سلوم لاش واخستلو او په ځنګل کښې يې په يوه ډُوبه کنده کښې وغورزولو او د کاڼو په يو ډېرى باندې يې پټ کړو. ټول بنى اِسرائيليان خپلو کورونو ته وتښتېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7979, '2 Samuel 18:18', '2 Samuel', 18, 18, '&nbsp;ابى‌سلوم په خپل ژوند کښې د خپل ځان دپاره په شاهى وادۍ کښې يو يادګار جوړ کړے وو، ځکه چې د هغۀ زامن نۀ وُو چې د هغۀ نوم ژوندے پاتې شى. نو په دې باندې يې خپل نوم کېښودو او تر نن ورځې پورې دا د ابى‌سلوم په يادګار مشهور دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7980, '2 Samuel 18:19', '2 Samuel', 18, 19, '&nbsp;بيا د صدوق زوئ اخيمعض يوآب ته ووئيل، ”ما پرېږده چې د دې زېرى سره بادشاه له ورمنډه کړم چې مالِک خُدائ هغه د خپلو دشمنانو نه بچ کړے دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7981, '2 Samuel 18:20', '2 Samuel', 18, 20, '&nbsp;يوآب ووئيل، ”نه، نن به تۀ پېغام نۀ وړې بله ورځ به يې يوسې، ځکه چې د بادشاه زوئ مړ دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7982, '2 Samuel 18:21', '2 Samuel', 18, 21, '&nbsp;بيا هغۀ خپل د ايتهوپيا غلام ته ووئيل، ”لاړ شه تا چې څۀ ليدلى وى هغه بادشاه ته ووايه.“ غلام ټيټ شو او منډه يې کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7983, '2 Samuel 18:22', '2 Samuel', 18, 22, '&nbsp;اخيمعض ورته بيا بيا وئيل، ”چې څۀ کيږى نو هغه به کيږى خو ما پرېږده چې خبر يوسم.“ يوآب ترې نه تپوس وکړو، ”زما زويه، تۀ داسې ولې کوې؟ تا ته به د دې هيڅ فائده مِلاو نۀ شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7984, '2 Samuel 18:23', '2 Samuel', 18, 23, '&nbsp;اخيمعض بيا ووئيل، ”چې څۀ هم کيږى زۀ تلل غواړم.“ يوآب ورته ووئيل، ”نو بيا لاړ شه.“ نو اخيمعض لاندې د اُردن په مېدان کښې په سړک باندې منډه کړه او زر د غلام نه مخکښې تېر شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7985, '2 Samuel 18:24', '2 Samuel', 18, 24, '&nbsp;داؤد ښار ته د ننوتو او بهر ته راوتو دروازو په مينځ کښې ناست وو. محافظ د دېوال سر ته وختلو او د دروازې په خولۀ کښې په چت باندې ودرېدو، هغۀ بهر وکتل او وې وليدل چې يو سړے يواځې منډې راوهى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7986, '2 Samuel 18:25', '2 Samuel', 18, 25, '&nbsp;هغۀ لاندې آواز وکړو او بادشاه يې خبر کړو او بادشاه وفرمائيل، ”کۀ هغه يواځې وى، نو هغۀ به يو زېرے راروان کړے وى.“ هغه منډه وهونکے نور هم رانزدې کېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7987, '2 Samuel 18:26', '2 Samuel', 18, 26, '&nbsp;محافظ يو بل سړے وليدو چې يواځې يې منډې وهلې او هغۀ لاندې د دروازې محافظ ته آواز وکړو، ”ګوره، يو بل سړے هم منډې راوهى.“ بادشاه ورته وفرمائيل، ”هغۀ هم زېرے راروان کړے دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7988, '2 Samuel 18:27', '2 Samuel', 18, 27, '&nbsp;محافظ ووئيل، ”هغه وړومبے سړے داسې منډې وهى لکه چې اخيمعض وى.“ بادشاه ورته وفرمائيل، ”هغه ښۀ سړے دے او هغه به يو ښۀ زېرے راوړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7989, '2 Samuel 18:28', '2 Samuel', 18, 28, '&nbsp;اخيمعض بادشاه ته آواز وکړو، د هغۀ په مخکښې زمکې ته ټيټ شو او وې وئيل، ”د مالِک خُدائ ستا د خُدائ پاک ثناء صِفت دې وى، بادشاه سلامت. هغۀ تا له په هغه سړو باندې فتح درکړې ده چا چې ستا خِلاف بغاوت کړے وو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7990, '2 Samuel 18:29', '2 Samuel', 18, 29, '&nbsp;بادشاه تپوس وکړو، ”ولې هغه زلمے ابى‌سلوم بچ دے؟“ اخيمعض ورته ووئيل، ”بادشاه سلامت، کله چې ستا آفسر يوآب زۀ ولېږلم، نو ما د خلقو يوه لويه ګڼه وليده، خو ما ته پته ونۀ لګېده چې دا د څۀ ګڼه وه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7991, '2 Samuel 18:30', '2 Samuel', 18, 30, '&nbsp;بادشاه ورته وفرمائيل، ”هلته ودرېږه.“ نو هغه لاړو او هلته ودرېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7992, '2 Samuel 18:31', '2 Samuel', 18, 31, '&nbsp;بيا هغه د ايتهوپيا غلام راورسېدو او بادشاه ته يې ووئيل، ”بادشاه سلامت، ستا دپاره ما سره يو زېرے دے، مالِک خُدائ تا له نن په هغه ټولو باندې فتح درکړې ده چا چې ستا خِلاف بغاوت کړے دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7993, '2 Samuel 18:32', '2 Samuel', 18, 32, '&nbsp;بادشاه تپوس وکړو، ”هغه زلمے ابى‌سلوم بچ دے څۀ؟“ غلام ورته ووئيل، ”بادشاه سلامت، زۀ غواړم چې په هغۀ باندې څۀ شوى دى چې هغه ستا په ټولو دشمنانو او په هغوئ باندې شوى وے چا چې د بادشاه خِلاف بغاوت کړے دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7994, '2 Samuel 18:33', '2 Samuel', 18, 33, '&nbsp;بادشاه ډېر غمژن شو. د ښار په دروازه بره کوټې ته وختلو او ژړل يې او په چغو چغو يې ژړل، ”اے زما بچيه، زما زويه، ابى‌سلومه، ابى‌سلومه، زما زويه. کاش چې ستا په ځائ زۀ مړ وے، زما زويه. ابى‌سلومه، زما زويه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7995, '2 Samuel 19:1', '2 Samuel', 19, 1, '&nbsp;يوآب خبر شو چې داؤد بادشاه ژاړى او د ابى‌سلوم په غم غمژن دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7996, '2 Samuel 19:2', '2 Samuel', 19, 2, '&nbsp;نو په هغه ورځ د داؤد د ټولو فوجيانو د فتحې خوشحالى په غم بدله شوه، ځکه چې هغوئ خبر شول چې بادشاه په خپل زوئ باندې غم کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7997, '2 Samuel 19:3', '2 Samuel', 19, 3, '&nbsp;هغوئ پټ پټ ښار ته واپس لاړل، لکه څنګه چې هغه فوجيان شرميږى چې کوم د جنګ نه تښتى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7998, '2 Samuel 19:4', '2 Samuel', 19, 4, '&nbsp;بادشاه خپل مخ پټ کړے وو او په چغو چغو يې ژړل، ”اے زما زويه، زما زويه ابى‌سلومه. ابى‌سلومه، زما زويه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7999, '2 Samuel 19:5', '2 Samuel', 19, 5, '&nbsp;يوآب د بادشاه کور ته لاړو او ورته يې ووئيل، ”تا نن خپل هغه سړى سپک کړى دى چا چې ستا، ستا د زامنو، لوڼو، ستا د ښځو او ستا د وينځو ژوند بچ کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8000, '2 Samuel 19:6', '2 Samuel', 19, 6, '&nbsp;تۀ د هغه چا مخالفت کوې چې څوک درسره مينه کوى او چې څوک درنه نفرت کوى نو د هغوئ ملګرتيا کوې. تا دا خبره صفا کړې ده چې تا سره د خپلو آفسرانو او سړو هيڅ قدر نشته. ما ته پته ده چې تۀ به نن ښۀ خوشحاله وې چې ابى‌سلوم ژوندے وے او مونږ ټول مړۀ وے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');